// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 id) public {
        bool wasPending = c.isOperationPending(id);
        bool reverted;
        try c.cancel(id) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == !wasPending);
    }
}

